// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address nonAdmin = address(0x1234);
        address newOwner = address(0x5678);
        address originalOwner = c.owner();

        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok && c.owner() == originalOwner);
    }
}
